    for _ in range(80):
        mid=(lo+hi)/2
        r=relationship_cost(case, terms, std, {"standard":std,"interest_rate":rate,"full_cost":mid})
        lo,hi=(mid,hi) if r<rel else (lo,mid)
    return round(hi,2)
